public String balancedSumsBrute(int[] arr) {
    int n = arr.length;
    for (int i = 0; i < n; i++) {
        long left = 0, right = 0;
        for (int l = 0; l < i; l++) left += arr[l];
        for (int r = i + 1; r < n; r++) right += arr[r];
        if (left == right) return "YES";
    }
    return "NO";
}

