public String balancedSums(int[] arr) {
    long total = 0;
    for (int v : arr) total += v;
    long left = 0;
    for (int i = 0; i < arr.length; i++) {
        long right = total - left - arr[i];
        if (left == right) return "YES";
        left += arr[i];
    }
    return "NO";
}

